mapper.update:
UPDATE fortune_results
SET result_json = #{resultJson}, status = 'DONE', error = NULL
WHERE id = #{id}

UPDATE fortune_results
SET status = 'FAILED', error = #{error}
WHERE id = #{id}

UPDATE fortune_results
SET status = 'GENERATING', error = NULL
WHERE id = #{id}

mapper.select:
SELECT id, member_id, slug, payment_id, name, result_json, status, error, input_json, created_at
FROM fortune_results
WHERE id = #{id}

SELECT id, member_id, slug, payment_id, name, result_json, status, error, input_json, created_at
FROM fortune_results
WHERE payment_id = #{paymentId}

SELECT id, member_id, slug, payment_id, name, result_json, status, error, input_json, created_at
FROM fortune_results
WHERE id = #{id} AND member_id = #{memberId}
